这说明什么？说明 Actor 运行时本身没有任何延迟抖动，所有毛刺都是外部 CPU 抢占。生产环境的建议很简单：业务机器上别跑乱七八糟的定时任务。
技术要点：为什么这么快？简单说几个设计决策：
1. 消息对象池 + 引用计数
Actor 之间传递的消息通过自定义泛型对象池 zpool.Pool + 原子引用计数管理生命周期，热路径零堆分配。池化对象带 Prometheus 可观测指标，双重释放有告警。
（来自 zmsg/msgpool.go）
// GetMessage 从池中获取消息，初始引用计数 = 1
func GetMessage() *Message {
 msg := getMessagePool().Get()
 msg.PoolReset()
 atomic.StoreInt32(&msg.RefCount, 1)
 return msg
}

// Retain 引用计数 +1，返回自身以便链式调用
func (m *Message) Retain() *Message {
 if m == nil {
 return nil
 }
 newRef := atomic.AddInt32(&m.RefCount, 1)
 return m
}

// Release 引用计数 -1，降为 0 时自动回收到池
func (m *Message) Release() {
 if m == nil {
 return
 }
 newRef := atomic.AddInt32(&m.RefCount, -1)
 if newRef == 0 {
 if cap(m.Data) > 4096 {
 m.Data = nil // 大 buffer 不回池，防内存驻留
 }
 getMessagePool().Put(m)
 return
 }
 if newRef Actor A 把消息 Retain() 后投递给 Actor B，B 处理完 Release()，引用计数归零自动回池。全程无 GC 参与。还有防双释放保护和超大 buffer 自动丢弃的细节。
2. MPSC 邮箱 + 批量处理
每个 Actor 一个 MPSC（多生产者单消费者）邮箱。高性能的关键不是来一条处理一条，而是一口气读一批再分发：
（来自 zactor/base.go）
// Run 启动 Actor 主循环并处理 mailbox 命令，直到优雅退出
func (a *Actor) Run(ctx context.Context) {
 defer a.GetLogger().Recover(&#34;Group processActor&#34;)
 maxBatchSize := zmodel.GetFrameworkTuning().ActorBatchMax
 msgs := make([]zmodel.ActorCmd, maxBatchSize)

 idleCount := 0
 lastBatchSize := 1

 for {
 // ... 优雅退出检查省略 ...

 batchSize := a.batcher.GetBatchSize(int64(lastBatchSize))
 n := a.mailBoxQueue.DequeueBatch(msgs[:batchSize]) // 批量出队

 if n == 0 {
 idleCount++
 zbackoff.Backoff(idleCount, 10, 30, time.Millisecond) // 空闲退避
 lastBatchSize = 1
 continue
 }

 idleCount = 0
 lastBatchSize = n // 驱动下次批量大小预测

 // 批量共享时间戳，每 50 条刷新一次
 batchStartMs := ztime.ServerNowUnixMilli()
 const timestampRefreshInterval = 50

 for i := 0; i 0 && i%timestampRefreshInterval == 0 {
 batchStartMs = ztime.ServerNowUnixMilli()
 }
 a.SafeHandleMessage(handleCtx, msgs[i], batchStartMs)
 msgs[i].Release() // 处理完立即释放，回收到对象池
 }

 a.batcher.RecordLatency(time.Since(batchStart)) // 记录批处理延迟
 }
}几个细节值得注意：
自适应批量大小（FastAdaptiveBatcher）：根据上一批的大小动态调整下一批的读取量，负载高时批量更大共享时间戳：整批消息每 50 条刷新一次 time.Now()，4 万 QPS 下节省大量系统调用空闲退避：队列空时指数退避（10～30ms），让出 CPU3. 协程池
worker pool 固定 500，避免无限制地创建 goroutine。25 个 goroutine 搞定 2000 个长连接，资源利用率极高。
