 Msg: msg.Retain(), // 引用计数 +1，零拷贝跨 Actor 传递
 })
 return
 }
 }
 }

 // 3. 跨进程路由（走 NATS 消息总线，需序列化）
 if s.GetGroup() != nil && s.GetGroup().GetDiscoverer() != nil {
 if ok := s.routeToRemoteActor(msg); ok { return }
 }

 // 4. 无路由
 s.sendNoRouteError(msg)
}本进程内路由（步骤 2）就是一次 Retain() + 指针投递，没有序列化、没有深拷贝。只有跨进程路由（步骤 3）才需要序列化走消息总线。
总结zhenyi 框架层面的压测数据，我认为是扎实的：
✅ 7 天 121 亿消息长稳运行，QPS 和延迟无退化✅ 亚毫秒级回环延迟（P50 0.11ms）✅ 极低 GC 暂停（7 天总暂停 46 秒）✅ 零 goroutine 泄漏、零内存泄漏✅ 2000 连接仅需 25 个 goroutine这个性能不是靠什么黑魔法，就是老老实实地做对象池、批量处理、协程池管控。Go 写高性能服务，方向对了效果是很好的。
